select count(*)
from t_model a,
     JSON_TABLE(models, '$[*]' COLUMNS (id VARCHAR(255) PATH '$.id')
     ) b
where a.is_delete = 0 and b.id = #{id};

select count(*)
from t_chat_room_structure a,
     JSON_TABLE(roles_set, '$[*]' COLUMNS (models VARCHAR(255) PATH '$.models')
     ) b
where a.is_deleted = 0 and models = #{id};
